/* Autonomous Studio — all content is read from site/data (generated by build.py). */
async function j(p){ try{ const r=await fetch("data/"+p); return r.ok? r.json():null }catch(e){ return null } }
async function t(p){ try{ const r=await fetch("data/"+p); return r.ok? r.text():null }catch(e){ return null } }
const el=id=>document.getElementById(id);
const esc=s=>String(s).replace(/[&<>"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]));

async function common(){
  const n=await t("name.txt");
  if(n&&n.trim()&&el("company-name")) el("company-name").textContent=n.trim();
}

async function dashboard(){
  if(!el("events")) return;
  const g=await j("changelog.json");
  if(g&&g.length) el("events").innerHTML=g.slice(0,12).map(x=>
    `<div class="row"><span>${esc(x.message)}</span><span class="muted">${esc(x.date)}</span></div>`).join("");
  const m=await j("manifest.json"); if(!m) return;
  const hall=m.files.filter(d=>d.startsWith("hallway/")).sort().slice(-6);
  if(hall.length){
    const lines=await Promise.all(hall.map(k=>t(k)));
    el("hallway").innerHTML=lines.filter(Boolean).map(s=>`<div class="row"><span>${esc(s.trim())}</span></div>`).join("");
  }
}

async function predictionDesk(){
  if(!el("league-table")) return;
  const lg=await j("league.json");
  if(lg){
    const p=Object.entries(lg.personas).sort((a,b)=>b[1].points-a[1].points);
    el("league-table").innerHTML="<table><tr><th>Persona</th><th>Points</th><th>Exact scores</th><th>Correct outcomes</th><th>Weeks</th></tr>"+
      p.map(([n,k])=>`<tr><td>${esc(n)}</td><td>${k.points}</td><td>${k.exact}</td><td>${k.outcome}</td><td>${k.weeks}</td></tr>`).join("")+"</table>";
    if(window.Chart&&el("league-chart")) new Chart(el("league-chart"),{type:"bar",
      data:{labels:p.map(x=>x[0]),datasets:[{label:"points",data:p.map(x=>x[1].points),backgroundColor:"#5b8cff"}]},
      options:{plugins:{legend:{display:false}},scales:{y:{beginAtZero:true,ticks:{color:"#9aa3b5"}},x:{ticks:{color:"#9aa3b5"}}}}});
  }
  const m=await j("manifest.json"); if(!m) return;
  const sets=m.files.filter(d=>/^predictions\/.+\.json$/.test(d)).sort();
  if(!sets.length) return;
  const weeks=[...new Set(sets.map(d=>d.split("/").pop().replace(".json","")))].sort();
  const last=weeks[weeks.length-1];
  let html="";
  for(const d of sets.filter(x=>x.endsWith(last+".json"))){
    const persona=d.split("/")[1], data=await j(d); if(!data) continue;
    html+=`<h3 class="muted" style="margin-top:14px">${esc(persona)} — ${esc(last)}</h3>`+
      data.map(x=>`<div class="row"><span>${esc(x.home)} ${esc(x.score)} ${esc(x.away)}</span><span class="muted">${esc(x.reasoning)}</span></div>`).join("");
  }
  if(html) el("prediction-list").innerHTML=html;
  el("archive").innerHTML=weeks.map(w=>`<span class="badge" style="margin-right:8px">${esc(w)}</span>`).join("")||el("archive").innerHTML;
}

async function office(){
  if(!el("roster")) return;
  const r=await j("roster.json");
  if(r) el("roster").innerHTML=r.map(a=>
    `<div class="card"><h3>${esc(a.name)}</h3><p>${esc(a.role)} · shifts: ${a.shifts.join(", ")}</p>
     <p><a href="#" data-prompt="${esc(a.id)}">view prompt</a></p><pre hidden id="p-${esc(a.id)}"></pre></div>`).join("");
  document.querySelectorAll("[data-prompt]").forEach(x=>x.addEventListener("click",async e=>{
    e.preventDefault(); const id=x.dataset.prompt, pre=el("p-"+id);
    if(!pre.hidden){pre.hidden=true;return}
    pre.textContent=(await t("prompts/"+id+".md"))||"prompt unavailable"; pre.hidden=false;
  }));
  const m=await j("manifest.json"); if(!m) return;
  const mins=m.files.filter(d=>d.startsWith("minutes/")).sort().reverse().slice(0,20);
  if(mins.length){
    el("minutes").innerHTML=mins.map(d=>`<div class="row"><a href="#" data-min="${esc(d)}">${esc(d.replace("minutes/",""))}</a></div><pre hidden id="m-${esc(d)}"></pre>`).join("");
    document.querySelectorAll("[data-min]").forEach(x=>x.addEventListener("click",async e=>{
      e.preventDefault(); const d=x.dataset.min, pre=document.getElementById("m-"+d);
      if(!pre.hidden){pre.hidden=true;return}
      pre.textContent=(await t(d))||"unavailable"; pre.hidden=false;
    }));
  }
}

async function changelog(){
  if(!el("changelog")) return;
  const g=await j("changelog.json");
  if(g&&g.length) el("changelog").innerHTML="<table><tr><th>Date</th><th>Change</th></tr>"+
    g.map(x=>`<tr><td class="muted">${esc(x.date)}</td><td>${esc(x.message)}</td></tr>`).join("")+"</table>";
}

common(); dashboard(); predictionDesk(); office(); changelog();
